// PURE: the app's mapping (public/mapping.json), validated once at import, and
// voice lookup by id. Every other mapping module reads the numbers from here.

import raw from "../../../public/mapping.json";
// The official records' voices, generated by pipeline/svs/records/voices.py (their input ranges are pipeline output).
import official from "../../../public/mapping-official.json";
import type { MappingSpec, VoiceSpec } from "@/types/data-contract";
import { MappingError, validateMapping } from "./mapping-validate";

// The app's mapping (hand-written voices + the generated official ones), validated once at import. A bad file fails
// loudly at start-up.
export const MAPPING: MappingSpec = validateMapping({ ...raw, voices: [...raw.voices, ...official.voices] });

/** The app's own voices (public/mapping.json): the rules the Mapping panel and How we know list. The official
 *  records' generated voices are shown with each record instead. */
const APP_VOICE_IDS = new Set(raw.voices.map((v) => v.id));
export const APP_VOICES: readonly VoiceSpec[] = MAPPING.voices.filter((v) => APP_VOICE_IDS.has(v.id));

/** Looks up a voice (or earcon) by id. Throws if it isn't in mapping.json. */
export function voiceSpec(id: string, spec: MappingSpec = MAPPING): VoiceSpec {
  const v = spec.voices.find((x) => x.id === id);
  if (!v) throw new MappingError(`no voice with id "${id}"`);
  return v;
}
